import sqlite3
import os
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        email TEXT,
        department TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        username TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    admin_hash = hashlib.sha256(b'supersecret').hexdigest()
    db.execute("INSERT OR IGNORE INTO users (username, password_hash, role, email, department) VALUES (?, ?, ?, ?, ?)",
               ('admin', admin_hash, 'admin', 'admin@corp.local', 'IT'))
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department or role. Supports partial matching."""
    field = request.args.get('field', 'department')
    value = request.args.get('value', '')

    # Validate field name against allowed columns
    allowed_fields = ['department', 'role', 'email', 'username']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Build query - field is validated above, value is user-controlled
    query = f"SELECT username, email, department, role FROM users WHERE {field} LIKE '%{value}%'"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]

        # Log the search action
        db.execute("INSERT INTO audit_log (action, username) VALUES (?, ?)",
                   (f'search:{field}', request.remote_addr))
        db.commit()

        return jsonify({'users': users, 'count': len(users)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/users/profile', methods=['GET'])
def get_profile():
    """Get user profile by username - uses parameterized query."""
    username = request.args.get('username', '')
    db = get_db()
    result = db.execute("SELECT username, email, department, role FROM users WHERE username = ?", (username,)).fetchone()
    if result:
        return jsonify(dict(result))
    return jsonify({'error': 'User not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user account."""
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    password_hash = hashlib.sha256(data['password'].encode()).hexdigest()
    db = get_db()
    try:
        db.execute("INSERT INTO users (username, password_hash, role, email, department) VALUES (?, ?, ?, ?, ?)",
                   (data['username'], password_hash, 'user', data.get('email', ''), data.get('department', '')))
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.4'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
